-- Create users profiles table
CREATE TABLE IF NOT EXISTS public.users (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  phone TEXT,
  photo_url TEXT,
  role TEXT NOT NULL CHECK (role IN ('Adult', 'Parent', 'Child', 'Roommate')),
  household_id UUID,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;

-- RLS Policies for users
CREATE POLICY "Users can view their own profile"
  ON public.users FOR SELECT
  USING (auth.uid() = id);

CREATE POLICY "Users can view household members"
  ON public.users FOR SELECT
  USING (
    household_id IS NOT NULL 
    AND household_id IN (
      SELECT household_id FROM public.users WHERE id = auth.uid()
    )
  );

CREATE POLICY "Users can update their own profile"
  ON public.users FOR UPDATE
  USING (auth.uid() = id);

-- Create index for faster lookups
CREATE INDEX idx_users_household_id ON public.users(household_id);
CREATE INDEX idx_users_email ON public.users(email);

-- Create households table
CREATE TABLE IF NOT EXISTS public.households (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  address TEXT,
  created_by_user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
  members_count INTEGER DEFAULT 1,
  invite_code TEXT UNIQUE NOT NULL DEFAULT substring(md5(random()::text) from 1 for 8),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE public.households ENABLE ROW LEVEL SECURITY;

-- RLS Policies for households
CREATE POLICY "Users can view their own household"
  ON public.households FOR SELECT
  USING (
    id IN (
      SELECT household_id FROM public.users WHERE id = auth.uid()
    )
  );

CREATE POLICY "Users can create households"
  ON public.households FOR INSERT
  WITH CHECK (created_by_user_id = auth.uid());

CREATE POLICY "Household creators can update their household"
  ON public.households FOR UPDATE
  USING (created_by_user_id = auth.uid());

-- Create index for faster lookups
CREATE INDEX idx_households_invite_code ON public.households(invite_code);
CREATE INDEX idx_households_created_by ON public.households(created_by_user_id);

-- Create tasks table
CREATE TABLE IF NOT EXISTS public.tasks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id UUID NOT NULL REFERENCES public.households(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  description TEXT,
  assigned_to_user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
  frequency TEXT NOT NULL CHECK (frequency IN ('one-time', 'daily', 'weekly', 'monthly')),
  due_date TIMESTAMP WITH TIME ZONE,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'in-progress', 'completed')),
  created_by_user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
  completed_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;

-- RLS Policies for tasks
CREATE POLICY "Household members can view tasks"
  ON public.tasks FOR SELECT
  USING (
    household_id IN (
      SELECT household_id FROM public.users WHERE id = auth.uid()
    )
  );

CREATE POLICY "Adults can create tasks"
  ON public.tasks FOR INSERT
  WITH CHECK (
    household_id IN (
      SELECT household_id FROM public.users 
      WHERE id = auth.uid() 
      AND role IN ('Adult', 'Parent')
    )
  );

CREATE POLICY "Adults can update tasks"
  ON public.tasks FOR UPDATE
  USING (
    household_id IN (
      SELECT household_id FROM public.users 
      WHERE id = auth.uid() 
      AND role IN ('Adult', 'Parent')
    )
  );

CREATE POLICY "Assigned users can mark tasks complete"
  ON public.tasks FOR UPDATE
  USING (assigned_to_user_id = auth.uid())
  WITH CHECK (assigned_to_user_id = auth.uid());

CREATE POLICY "Adults can delete tasks"
  ON public.tasks FOR DELETE
  USING (
    household_id IN (
      SELECT household_id FROM public.users 
      WHERE id = auth.uid() 
      AND role IN ('Adult', 'Parent')
    )
  );

-- Create indexes
CREATE INDEX idx_tasks_household_id ON public.tasks(household_id);
CREATE INDEX idx_tasks_assigned_to ON public.tasks(assigned_to_user_id);
CREATE INDEX idx_tasks_due_date ON public.tasks(due_date);
CREATE INDEX idx_tasks_status ON public.tasks(status);

-- Create shopping items table
CREATE TABLE IF NOT EXISTS public.shopping_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id UUID NOT NULL REFERENCES public.households(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  quantity TEXT,
  category TEXT,
  added_by_user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
  purchased BOOLEAN DEFAULT FALSE,
  purchased_by_user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
  purchased_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE public.shopping_items ENABLE ROW LEVEL SECURITY;

-- RLS Policies for shopping items
CREATE POLICY "Household members can view shopping items"
  ON public.shopping_items FOR SELECT
  USING (
    household_id IN (
      SELECT household_id FROM public.users WHERE id = auth.uid()
    )
  );

CREATE POLICY "Household members can create shopping items"
  ON public.shopping_items FOR INSERT
  WITH CHECK (
    household_id IN (
      SELECT household_id FROM public.users WHERE id = auth.uid()
    )
  );

CREATE POLICY "Household members can update shopping items"
  ON public.shopping_items FOR UPDATE
  USING (
    household_id IN (
      SELECT household_id FROM public.users WHERE id = auth.uid()
    )
  );

CREATE POLICY "Adults can delete shopping items"
  ON public.shopping_items FOR DELETE
  USING (
    household_id IN (
      SELECT household_id FROM public.users 
      WHERE id = auth.uid() 
      AND role IN ('Adult', 'Parent')
    )
  );

-- Create indexes
CREATE INDEX idx_shopping_items_household_id ON public.shopping_items(household_id);
CREATE INDEX idx_shopping_items_purchased ON public.shopping_items(purchased);

-- Create household events table
CREATE TABLE IF NOT EXISTS public.household_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id UUID NOT NULL REFERENCES public.households(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  date DATE NOT NULL,
  time TIME,
  description TEXT,
  created_by_user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
  assigned_to_user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
  repeat TEXT NOT NULL DEFAULT 'none' CHECK (repeat IN ('none', 'daily', 'weekly', 'monthly')),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE public.household_events ENABLE ROW LEVEL SECURITY;

-- RLS Policies for household events
CREATE POLICY "Household members can view events"
  ON public.household_events FOR SELECT
  USING (
    household_id IN (
      SELECT household_id FROM public.users WHERE id = auth.uid()
    )
  );

CREATE POLICY "Adults can create events"
  ON public.household_events FOR INSERT
  WITH CHECK (
    household_id IN (
      SELECT household_id FROM public.users 
      WHERE id = auth.uid() 
      AND role IN ('Adult', 'Parent')
    )
  );

CREATE POLICY "Adults can update events"
  ON public.household_events FOR UPDATE
  USING (
    household_id IN (
      SELECT household_id FROM public.users 
      WHERE id = auth.uid() 
      AND role IN ('Adult', 'Parent')
    )
  );

CREATE POLICY "Adults can delete events"
  ON public.household_events FOR DELETE
  USING (
    household_id IN (
      SELECT household_id FROM public.users 
      WHERE id = auth.uid() 
      AND role IN ('Adult', 'Parent')
    )
  );

-- Create indexes
CREATE INDEX idx_household_events_household_id ON public.household_events(household_id);
CREATE INDEX idx_household_events_date ON public.household_events(date);

-- Create expenses table
CREATE TABLE IF NOT EXISTS public.expenses (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id UUID NOT NULL REFERENCES public.households(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  amount DECIMAL(10, 2) NOT NULL,
  category TEXT,
  created_by_user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
  paid_by_user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
  date DATE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE public.expenses ENABLE ROW LEVEL SECURITY;

-- RLS Policies for expenses
CREATE POLICY "Household members can view expenses"
  ON public.expenses FOR SELECT
  USING (
    household_id IN (
      SELECT household_id FROM public.users WHERE id = auth.uid()
    )
  );

CREATE POLICY "Adults can create expenses"
  ON public.expenses FOR INSERT
  WITH CHECK (
    household_id IN (
      SELECT household_id FROM public.users 
      WHERE id = auth.uid() 
      AND role IN ('Adult', 'Parent')
    )
  );

CREATE POLICY "Adults can update expenses"
  ON public.expenses FOR UPDATE
  USING (
    household_id IN (
      SELECT household_id FROM public.users 
      WHERE id = auth.uid() 
      AND role IN ('Adult', 'Parent')
    )
  );

CREATE POLICY "Adults can delete expenses"
  ON public.expenses FOR DELETE
  USING (
    household_id IN (
      SELECT household_id FROM public.users 
      WHERE id = auth.uid() 
      AND role IN ('Adult', 'Parent')
    )
  );

-- Create indexes
CREATE INDEX idx_expenses_household_id ON public.expenses(household_id);
CREATE INDEX idx_expenses_date ON public.expenses(date);

-- Create notifications table
CREATE TABLE IF NOT EXISTS public.notifications (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  household_id UUID NOT NULL REFERENCES public.households(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  message TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('task', 'event', 'shopping', 'expense', 'invitation', 'general')),
  read BOOLEAN DEFAULT FALSE,
  related_id UUID,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

-- RLS Policies for notifications
CREATE POLICY "Users can view their own notifications"
  ON public.notifications FOR SELECT
  USING (user_id = auth.uid());

CREATE POLICY "Users can update their own notifications"
  ON public.notifications FOR UPDATE
  USING (user_id = auth.uid());

CREATE POLICY "Users can delete their own notifications"
  ON public.notifications FOR DELETE
  USING (user_id = auth.uid());

-- Create indexes
CREATE INDEX idx_notifications_user_id ON public.notifications(user_id);
CREATE INDEX idx_notifications_read ON public.notifications(read);
CREATE INDEX idx_notifications_created_at ON public.notifications(created_at DESC);

-- Create function to update updated_at timestamp
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create triggers for all tables with updated_at
CREATE TRIGGER update_users_updated_at
  BEFORE UPDATE ON public.users
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_households_updated_at
  BEFORE UPDATE ON public.households
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_tasks_updated_at
  BEFORE UPDATE ON public.tasks
  FOR EACH ROW
  EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_shopping_items_updated_at
