ALTER PUBLICATION supabase_realtime ADD TABLE shopping_items;
ALTER PUBLICATION supabase_realtime ADD TABLE household_events;
ALTER PUBLICATION supabase_realtime ADD TABLE notifications;

-- Add INSERT policy for users table (needed for signup)
CREATE POLICY "Users can insert their own profile"
ON users
FOR INSERT
WITH CHECK (auth.uid() = id);

-- Add policy to allow users to view households by invite code (needed for join)
CREATE POLICY "Users can view households by invite code"
ON households
FOR SELECT
USING (invite_code IS NOT NULL);

SELECT tablename, schemaname 
FROM pg_publication_tables 
WHERE pubname = 'supabase_realtime';

-- Fix RLS policies to use 'to authenticated' instead of 'to public'
-- This ensures only authenticated users can access the data

-- Drop all existing policies
