DROP POLICY IF EXISTS "Adults can create tasks" ON tasks;
DROP POLICY IF EXISTS "Adults can update tasks" ON tasks;
DROP POLICY IF EXISTS "Adults can delete tasks" ON tasks;
DROP POLICY IF EXISTS "Assigned users can mark tasks complete" ON tasks;

