DROP POLICY IF EXISTS "Household members can create shopping items" ON shopping_items;
DROP POLICY IF EXISTS "Household members can update shopping items" ON shopping_items;
DROP POLICY IF EXISTS "Adults can delete shopping items" ON shopping_items;

