DROP POLICY IF EXISTS "Adults can create events" ON household_events;
DROP POLICY IF EXISTS "Adults can update events" ON household_events;
DROP POLICY IF EXISTS "Adults can delete events" ON household_events;

DROP POLICY IF EXISTS "Household members can view expenses" ON expenses;
DROP POLICY IF EXISTS "Adults can create expenses" ON expenses;
DROP POLICY IF EXISTS "Adults can update expenses" ON expenses;
DROP POLICY IF EXISTS "Adults can delete expenses" ON expenses;

DROP POLICY IF EXISTS "Users can view their own notifications" ON notifications;
DROP POLICY IF EXISTS "Users can update their own notifications" ON notifications;
DROP POLICY IF EXISTS "Users can delete their own notifications" ON notifications;

-- USERS TABLE POLICIES
CREATE POLICY "Users can view their own profile"
  ON users FOR SELECT
  TO authenticated
  USING (auth.uid() = id);

CREATE POLICY "Users can view household members"
  ON users FOR SELECT
  TO authenticated
  USING (
    household_id IS NOT NULL 
    AND household_id IN (
      SELECT household_id FROM users WHERE id = auth.uid()
    )
  );

CREATE POLICY "Users can update their own profile"
