-- Children can only mark their assigned tasks as complete (status field only)
CREATE POLICY "Assigned users can mark tasks complete"
  ON tasks FOR UPDATE
  TO authenticated
  USING (assigned_to_user_id = auth.uid())
  WITH CHECK (
    assigned_to_user_id = auth.uid()
    -- This policy allows children to update only their assigned tasks
