-- Improve invite code generation to be more secure and less predictable
-- Use a combination of random UUID and timestamp for better uniqueness

-- Create a function to generate secure invite codes
CREATE OR REPLACE FUNCTION generate_secure_invite_code()
RETURNS TEXT AS $$
DECLARE
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- Removed ambiguous characters
  result TEXT := '';
  i INTEGER;
BEGIN
  FOR i IN 1..8 LOOP
    result := result || substr(chars, floor(random() * length(chars) + 1)::int, 1);
  END LOOP;
  RETURN result;
END;
$$ LANGUAGE plpgsql VOLATILE;

-- Update the households table to use the new function
ALTER TABLE households 
  ALTER COLUMN invite_code 
  SET DEFAULT generate_secure_invite_code();

-- Add a function to prevent role escalation from client side
CREATE OR REPLACE FUNCTION prevent_role_escalation()
RETURNS TRIGGER AS $$
BEGIN
  -- If user is trying to change their own role
  IF NEW.id = auth.uid() THEN
    -- Children cannot change their role
    IF OLD.role = 'Child' AND NEW.role != OLD.role THEN
      RAISE EXCEPTION 'Children cannot change their own role';
    END IF;

    -- Users cannot escalate to Parent role without admin approval
    IF OLD.role != 'Parent' AND NEW.role = 'Parent' THEN
      RAISE EXCEPTION 'Role escalation to Parent requires admin approval';
    END IF;
  END IF;

  RETURN NEW;
