-- Add a function to validate task updates for children
CREATE OR REPLACE FUNCTION validate_child_task_update()
RETURNS TRIGGER AS $$
DECLARE
  user_role TEXT;
BEGIN
  -- Get the user's role
  SELECT role INTO user_role FROM users WHERE id = auth.uid();

  -- If user is a child and assigned to this task
  IF user_role = 'Child' AND NEW.assigned_to_user_id = auth.uid() THEN
    -- Only allow status and completed_at changes
    IF OLD.title IS DISTINCT FROM NEW.title OR
       OLD.description IS DISTINCT FROM NEW.description OR
       OLD.assigned_to_user_id IS DISTINCT FROM NEW.assigned_to_user_id OR
       OLD.frequency IS DISTINCT FROM NEW.frequency OR
       OLD.due_date IS DISTINCT FROM NEW.due_date OR
       OLD.household_id IS DISTINCT FROM NEW.household_id OR
       OLD.created_by_user_id IS DISTINCT FROM NEW.created_by_user_id THEN
      RAISE EXCEPTION 'Children can only update task status and completion';
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

