-- Function to increment vote count
create or replace function increment_vote_count(option_uuid uuid)
returns void as $$
begin
  update poll_options
  set vote_count = vote_count + 1
  where id = option_uuid;
end;
$$ language plpgsql security definer;

-- Function to decrement vote count
create or replace function decrement_vote_count(option_uuid uuid)
returns void as $$
begin
  update poll_options
  set vote_count = greatest(vote_count - 1, 0)
  where id = option_uuid;
end;
$$ language plpgsql security definer;

-- Fix search_path security vulnerability for all 7 affected functions
-- This prevents search_path hijacking attacks by explicitly setting safe schemas

-- Function 1: is_household_admin
CREATE OR REPLACE FUNCTION public.is_household_admin(household_uuid uuid, user_uuid uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public, pg_temp'
AS $function$
begin
  return exists (
    select 1 from households
    where id = household_uuid
    and (created_by_user_id = user_uuid or user_uuid = any(admin_user_ids))
  );
end;
$function$;

-- Function 2: increment_vote_count
CREATE OR REPLACE FUNCTION public.increment_vote_count(option_uuid uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public, pg_temp'
AS $function$
begin
  update poll_options
  set vote_count = vote_count + 1
  where id = option_uuid;
end;
$function$;

-- Function 3: decrement_vote_count
CREATE OR REPLACE FUNCTION public.decrement_vote_count(option_uuid uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public, pg_temp'
AS $function$
begin
  update poll_options
  set vote_count = greatest(vote_count - 1, 0)
  where id = option_uuid;
end;
$function$;

-- Function 4: generate_secure_invite_code
CREATE OR REPLACE FUNCTION public.generate_secure_invite_code()
RETURNS text
LANGUAGE plpgsql
SET search_path = 'public, pg_temp'
AS $function$
DECLARE
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- Removed ambiguous characters
  result TEXT := '';
  i INTEGER;
BEGIN
  FOR i IN 1..8 LOOP
    result := result || substr(chars, floor(random() * length(chars) + 1)::int, 1);
  END LOOP;
  RETURN result;
END;
$function$;

-- Function 5: update_updated_at_column
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = 'public, pg_temp'
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$;

-- Function 6: get_current_user_household_id
CREATE OR REPLACE FUNCTION public.get_current_user_household_id()
RETURNS uuid
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path = 'public, pg_temp'
AS $function$
  SELECT household_id FROM public.users WHERE id = auth.uid() LIMIT 1;
$function$;

-- Function 7: prevent_role_escalation
CREATE OR REPLACE FUNCTION public.prevent_role_escalation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public, pg_temp'
AS $function$
BEGIN
  -- If user is trying to change their own role
  IF NEW.id = auth.uid() THEN
    -- Children cannot change their role
    IF OLD.role = 'Child' AND NEW.role != OLD.role THEN
      RAISE EXCEPTION 'Children cannot change their own role';
    END IF;

    -- Users cannot escalate to Parent role without admin approval
    IF OLD.role != 'Parent' AND NEW.role = 'Parent' THEN
      RAISE EXCEPTION 'Role escalation to Parent requires admin approval';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

