-- Shopping item comments indexes
DROP INDEX IF EXISTS idx_shopping_item_comments_shopping_item_id;

-- Create missing foreign key indexes for performance optimization
-- These indexes are critical for JOIN performance and preventing table locks

-- meal_ingredients table (2 indexes)
CREATE INDEX IF NOT EXISTS idx_meal_ingredients_meal_id 
ON meal_ingredients(meal_id);

CREATE INDEX IF NOT EXISTS idx_meal_ingredients_shopping_item_id 
ON meal_ingredients(shopping_item_id);

-- notifications table
CREATE INDEX IF NOT EXISTS idx_notifications_household_id 
ON notifications(household_id);

-- poll_comments table
CREATE INDEX IF NOT EXISTS idx_poll_comments_poll_id 
ON poll_comments(poll_id);

-- poll_options table
CREATE INDEX IF NOT EXISTS idx_poll_options_poll_id 
ON poll_options(poll_id);

-- shopping_item_comments table
CREATE INDEX IF NOT EXISTS idx_shopping_item_comments_shopping_item_id 
ON shopping_item_comments(shopping_item_id);

-- task_comments table
CREATE INDEX IF NOT EXISTS idx_task_comments_task_id 
ON task_comments(task_id);

-- Add comments to document the purpose of these indexes
COMMENT ON INDEX idx_meal_ingredients_meal_id IS 'Foreign key index for meal_ingredients.meal_id - improves JOIN performance';
COMMENT ON INDEX idx_meal_ingredients_shopping_item_id IS 'Foreign key index for meal_ingredients.shopping_item_id - improves JOIN performance';
COMMENT ON INDEX idx_notifications_household_id IS 'Foreign key index for notifications.household_id - improves JOIN performance';
COMMENT ON INDEX idx_poll_comments_poll_id IS 'Foreign key index for poll_comments.poll_id - improves JOIN performance';
COMMENT ON INDEX idx_poll_options_poll_id IS 'Foreign key index for poll_options.poll_id - improves JOIN performance';
COMMENT ON INDEX idx_shopping_item_comments_shopping_item_id IS 'Foreign key index for shopping_item_comments.shopping_item_id - improves JOIN performance';
COMMENT ON INDEX idx_task_comments_task_id IS 'Foreign key index for task_comments.task_id - improves JOIN performance';
